import re, unicodedata
def norm(s):
    s = unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode().upper()
    s = re.sub(r"[^A-Z ]", " ", s)
    s = re.sub(r"(.)\1+", r"\1", s)   # o Sankhya colapsa letras repetidas (SERRA -> SERA)
    return re.sub(r"\s+", " ", s).strip()
